from lib import *
S = SS('t12')
steps = [
    step("轮询发布:同一张 outbox 表,relay 每隔固定时间查一次“还没发出的行”。每种间隔发 150 个事件(平均每 15 ms 一个),延迟是从事务提交前一刻到消费者收到。每 10 ms 轮询:中位数 7.0 ms、p99 14.2 ms,但数据库空闲时每秒也要完成约 82 个事务;每 100 ms 轮询:中位数 54.1 ms、p99 104.2 ms,空闲时每秒 10 个;每 1000 ms 轮询:中位数 552.7 ms、p99 994.9 ms,空闲时每秒 1 个。延迟约等于“等到下一次轮询”的时间(间隔的一半左右),间隔越短、空闲时对数据库的无谓查询越多。", t=tl(S(1)), mark=lidx(S(1), '每 10 ms 轮询一次'), done=lidx(S(1), '每 1000 ms 轮询一次'), b=bars([['10 ms 轮询:延迟中位数 ms', 7.0, '7.0'], ['100 ms 轮询:延迟中位数 ms', 54.1, '54.1'], ['1000 ms 轮询:延迟中位数 ms', 552.7, '552.7'], ['10 ms 轮询:空闲事务数/秒', 82, '82']], 560, cur=[0, 1, 2], mark=[3]), kv=KV([['延迟', '≈ 轮询间隔的一半'], ['10 ms 间隔', '延迟 7.0 ms,空闲 82 事务/秒'], ['1000 ms 间隔', '延迟 552.7 ms,空闲 1 事务/秒']], ['延迟'])),
    step("自增 id 的顺序不是提交顺序。T1 先拿到较小的 id、后提交,T2 后拿到 id、先提交。“记住上次读到的最大 id”的游标轮询,只要恰好在“T2 已提交、T1 还没提交”的间隙里跑了一次(这里设成 50% 的概率),就把游标推过了 T1 的 id,T1 提交后永远读不到:300 组共 600 个事件,游标轮询只读到 458 个,丢了 142 个。标志位轮询(where not sent)不依赖 id 的顺序:600 个全部读到,丢 0。", t=tl(S(2)), mark=lidx(S(2), '游标:id > 上次读到的最大 id'), done=lidx(S(2), '标志位:where not sent'), b=bars([['游标轮询:丢失的事件', 142, '142 / 600'], ['标志位轮询:丢失的事件', 0, '0 / 600']], 150, mark=[0], done=[1]), kv=KV([['游标 id > last', '丢 142 / 600'], ['标志位 where not sent', '丢 0 / 600'], ['原因', 'id 的顺序 ≠ 提交的顺序']], ['原因'])),
    step("多个 relay 同时轮询。预先放 20000 个事件、批大小 200,各配置 3 轮取中位数。不加锁:2 个 relay 在 Kafka 里收到 37800 条(重复 17800),4 个 relay 收到 58200 条(重复 38200),多开 relay 没有变快,只是重复;1 个 relay 发完 20000 个用时 0.19 s。加 FOR UPDATE SKIP LOCKED:2 个 relay 用时 0.13 s、4 个 0.16 s,Kafka 里都是正好 20000 条、重复 0——每个 relay 只取没被别人锁住的行。", t=tl(S(3)), mark=lidx(S(3), '4 个 relay,不加锁'), done=lidx(S(3), '2 个 relay,FOR UPDATE SKIP LOCKED', '4 个 relay,FOR UPDATE SKIP LOCKED'), b=bars([['2 个 relay 不加锁:重复条数', 17800, '17800'], ['4 个 relay 不加锁:重复条数', 38200, '38200'], ['2 个 relay SKIP LOCKED:重复条数', 0, '0'], ['4 个 relay SKIP LOCKED:重复条数', 0, '0']], 40000, mark=[0, 1], done=[2, 3]), kv=KV([['不加锁', '多个 relay 读到同一批行,大量重复'], ['SKIP LOCKED', '各取各的,重复 0'], ['吞吐', '1 个 0.19 s,2 个加锁 0.13 s']], ['SKIP LOCKED'])),
    step("CDC(PostgreSQL 逻辑解码,pg_recvlogical + test_decoding):不查表,直接读 WAL 里已提交事务的变更。同样的负载下延迟中位数 1.2 ms、p99 3.7 ms,数据库空闲时没有任何轮询事务(0)。对第二节同样的 300 组交错:600 个事件全部收到(丢失 0、重复 0),300 组里 Kafka 里的顺序都是 T2 在 T1 前面——事件按提交顺序出现,和 id 的大小无关。CDC 读的是 WAL,天然没有“id 顺序 ≠ 提交顺序”的问题。", t=tl(S(4)), mark=lidx(S(4), 'CDC(逻辑解码)'), done=lidx(S(4), '同样的 300 组'), b=bars([['CDC 延迟中位数 ms', 1.2, '1.2'], ['CDC 延迟 p99 ms', 3.7, '3.7'], ['CDC 丢失的事件', 0, '0 / 600'], ['T2 在 T1 前面的组数', 300, '300 / 300']], 300, cur=[0, 1], done=[2], mark=[3]), kv=KV([['延迟', '中位数 1.2 ms,p99 3.7 ms'], ['空闲负载', '0 事务/秒'], ['顺序', '按提交顺序,不丢']], ['顺序'])),
    step("CDC 的代价:复制槽会为还没读走的消费者保留 WAL。消费者停了、业务继续写(每个 payload 200 字节):写 3 万、6 万、9 万个事件后,槽分别落后 12.4 MiB、24.8 MiB、37.2 MiB,随写入线性增长。消费者回来后 0.7 s 追上 9 万个事件(131130 事件/秒),但刚追上就 checkpoint,槽仍落后 38045 KiB——槽的位置要等消费者向服务器汇报进度才会前进;消费者继续连着、过了 11 秒(pg_recvlogical 默认每 10 秒汇报一次),再 checkpoint 才变成 0 KiB。消费者长时间不回来,WAL 会一直堆下去。", t=tl(S(5)), mark=lidx(S(5), '共 90000 个', '刚追上就 checkpoint'), done=lidx(S(5), '过了 11 秒'), b=bars([['写 3 万个后槽落后 MiB', 12.4, '12.4'], ['写 6 万个后槽落后 MiB', 24.8, '24.8'], ['写 9 万个后槽落后 MiB', 37.2, '37.2'], ['汇报进度后槽落后 MiB', 0, '0']], 40, mark=[0, 1, 2], done=[3]), kv=KV([['消费者停了', '槽落后随写入线性增长'], ['追上之后', '要等汇报进度槽才前进'], ['风险', '长期不回来,WAL 一直堆']], ['风险'])),
]
A = mkartt('t12', 12, '分布式事务,Outbox,CDC,逻辑解码,PostgreSQL,Kafka,真实验证,动画演示',
    '实测 Outbox 的两种发布方式:轮询的延迟约等于间隔的一半(10 ms 间隔 7.0 ms,1000 ms 间隔 552.7 ms),游标轮询会因 id 顺序不等于提交顺序丢 142 / 600 个事件,多个 relay 不加锁重复 17800 条,SKIP LOCKED 为 0;CDC 延迟 1.2 ms、不丢、按提交顺序,代价是复制槽保留 WAL(9 万个事件落后 37.2 MiB)。',
    'Outbox 里的事件怎么送到消息队列?定时轮询表,还是读数据库的变更日志(CDC)?这篇用同一个 PostgreSQL 和 Kafka,把轮询的延迟与空闲负载、自增 id 顺序陷阱、多个 relay 的重复、CDC 的延迟顺序与 WAL 保留的代价逐一量出来。',
    [('7.0 ms vs 552.7 ms', '轮询间隔 10 ms 与 1000 ms 时的延迟中位数(CDC 是 1.2 ms)'), ('142 / 600', '“记住最大 id”的游标轮询丢失的事件数(标志位轮询与 CDC 都是 0)'), ('37.2 MiB', '消费者停了、写 9 万个 200 字节事件之后,CDC 复制槽落后的 WAL 量')],
    [('轮询的取舍', '<p>延迟约等于间隔的一半,间隔越短,数据库空闲时被问得越多。</p>'),
     ('自增 id 的陷阱', '<p>id 顺序是拿到号的顺序,不是提交顺序。游标 id > last 会永久错过后提交的小 id;用 where not sent 的标志位就不会。</p>'),
     ('多个 relay', '<p>不加锁时多个 relay 读到同一批行,大量重复;FOR UPDATE SKIP LOCKED 让它们各取各的。</p>'),
     ('CDC', '<p>读 WAL 里已提交的变更:延迟毫秒级、空闲时没有轮询、按提交顺序不丢事件。</p>'),
     ('CDC 的代价', '<p>复制槽会为没读走的消费者一直保留 WAL;消费者停了,槽的落后量随写入线性增长,追上之后还要等它汇报进度才释放。</p>')],
    steps,
    [ENV_T + '。本篇轮询和 CDC 用的是同一个 PostgreSQL 16.15(wal_level=logical)和同一张 outbox 表,Kafka 4.3.1 单节点;CDC 用 pg_recvlogical + test_decoding 插件,我写的程序解析输出再发到 Kafka;延迟用同一台机器上的时钟,从事务提交前一刻算到消费者收到;第二节里“轮询落在间隙里”的 50% 概率是我设的',
     '没有验证:MySQL binlog 作为 CDC 来源(本篇用的是 PostgreSQL);Debezium 等产品的实际表现;pgoutput 插件(这里用 test_decoding);max_slot_wal_keep_size 对槽的保护(只在文字里提到,没有实验);长时间运行、大事务、DDL 变更下 CDC 的行为;pg_wal 目录的文件数在实验里保持 16 个没有变化,没有对此做进一步解释'],
    'Outbox 的发布')
